static boolean anagram(String a,String b){
    int[] x=a.codePoints().toArray(),y=b.codePoints().toArray();if(x.length!=y.length)return false;
    Map<Integer,Integer> counts=new HashMap<>();for(int c:x)counts.merge(c,1,Integer::sum);
    for(int c:y){int count=counts.getOrDefault(c,0);if(count==0)return false;if(count==1)counts.remove(c);else counts.put(c,count-1);}
    return counts.isEmpty();
}

