static String frequencySort(String s){
    Map<Integer,Integer> counts=new HashMap<>();s.codePoints().forEach(c->counts.merge(c,1,Integer::sum));
    List<Integer> keys=new ArrayList<>(counts.keySet());
    keys.sort((a,b)->{int cmp=Integer.compare(counts.get(b),counts.get(a));return cmp!=0?cmp:Integer.compare(a,b);});
    StringBuilder out=new StringBuilder();for(int c:keys)for(int i=0;i<counts.get(c);i++)out.appendCodePoint(c);
    return out.toString();
}

