static int maxDepth(String s){
    int depth=0,best=0;
    for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='(')best=Math.max(best,++depth);else if(c==')'&&--depth<0)throw new IllegalArgumentException();}
    if(depth!=0)throw new IllegalArgumentException();return best;
}

