static int romanValue(char c){
    return switch(c){case 'I'->1;case 'V'->5;case 'X'->10;case 'L'->50;case 'C'->100;case 'D'->500;case 'M'->1000;default->throw new IllegalArgumentException();};
}
static int fromRoman(String s){
    int total=0;for(int i=0;i<s.length();i++){int value=romanValue(s.charAt(i));total+=i+1<s.length()&&value<romanValue(s.charAt(i+1))?-value:value;}
    if(total<1||total>3999||!toRoman(total).equals(s))throw new IllegalArgumentException();return total;
}
static String toRoman(int number){
    if(number<1||number>3999)throw new IllegalArgumentException();
    int[] values={1000,900,500,400,100,90,50,40,10,9,5,4,1};
    String[] symbols={"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
    StringBuilder out=new StringBuilder();for(int i=0;i<values.length;i++)while(number>=values[i]){out.append(symbols[i]);number-=values[i];}return out.toString();
}

