static int atoi(String s){
    int i=0,sign=1;while(i<s.length()&&s.charAt(i)==' ')i++;
    if(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')){if(s.charAt(i)=='-')sign=-1;i++;}
    long value=0,limit=sign<0?2147483648L:2147483647L;
    while(i<s.length()&&s.charAt(i)>='0'&&s.charAt(i)<='9'){
        int digit=s.charAt(i++)-'0';if(value>(limit-digit)/10)return sign<0?Integer.MIN_VALUE:Integer.MAX_VALUE;
        value=value*10+digit;
    }
    return (int)(sign*value);
}

