static long atMost(int[] a,int k){
    if(k<0)return 0;Map<Integer,Integer> counts=new HashMap<>();int left=0;long answer=0;
    for(int right=0;right<a.length;right++){
        counts.merge(a[right],1,Integer::sum);
        while(counts.size()>k){int x=a[left++],count=counts.get(x);if(count==1)counts.remove(x);else counts.put(x,count-1);}
        answer+=right-left+1;
    }
    return answer;
}
static long exactlyK(int[] a,int k){return k<=0?0:atMost(a,k)-atMost(a,k-1);}
static long distinctSubstrings(String s,int k){return exactlyK(s.codePoints().toArray(),k);}

