static long beautySum(String s){
    long total=0;
    for(int left=0;left<s.length();left++){
        int[] counts=new int[26];
        for(int right=left;right<s.length();right++){
            counts[s.charAt(right)-'a']++;int high=0,low=Integer.MAX_VALUE;
            for(int count:counts)if(count>0){high=Math.max(high,count);low=Math.min(low,count);}
            total+=high-low;
        }
    }
    return total;
}

