static String reverseEachWord(String s){
    char[] a=s.toCharArray();int start=0;
    for(int end=0;end<=a.length;end++)if(end==a.length||a[end]==' '){
        for(int l=start,r=end-1;l<r;l++,r--){char t=a[l];a[l]=a[r];a[r]=t;}start=end+1;
    }
    return new String(a);
}
static String reverseWordOrder(String s){
    StringBuilder out=new StringBuilder();int i=s.length()-1;
    while(i>=0){while(i>=0&&s.charAt(i)==' ')i--;if(i<0)break;int end=i+1;
        while(i>=0&&s.charAt(i)!=' ')i--;if(out.length()>0)out.append(' ');out.append(s,i+1,end);
    }
    return out.toString();
}

