// Tracker / LeetCode 328: group by one-based POSITION.
static Node oddEvenPositions(Node head) {
    if (head == null || head.next == null) return head;
    Node odd = head;
    Node even = head.next;
    Node evenHead = even;
    while (even != null && even.next != null) {
        odd.next = even.next;
        odd = odd.next;
        even.next = odd.next;
        even = even.next;
    }
    odd.next = evenHead;
    return head;
}

// Current Striver article: even VALUES, then odd values.
static Node evenValuesFirst(Node head) {
    Node evenDummy = new Node(0);
    Node oddDummy = new Node(0);
    Node evenTail = evenDummy;
    Node oddTail = oddDummy;
    while (head != null) {
        Node next = head.next;
        head.next = null;
        if (head.data % 2 == 0) {
            evenTail.next = head;
            evenTail = head;
        } else {
            oddTail.next = head;
            oddTail = head;
        }
        head = next;
    }
    evenTail.next = oddDummy.next;
    return evenDummy.next;
}

